function subscribeForNewsletter(event) {
    event.stopPropagation();
    var script_tag = document.createElement('script');
    script_tag.setAttribute("type", "text/javascript");
    script_tag.setAttribute("src", "https://static.mailerlite.com/js/w/webforms.min.js?v28bf44f740701752bfc6767bc7e171d4");
    document.getElementsByTagName("head")[0].appendChild(script_tag);
    $(event.target).css('display', 'none');
    $('#mlb2-7341216').css('display', 'block');
}

body.script:
jqueryDefer(function () {
    $(window).scroll(function() {
        var height = $(window).scrollTop();
        var navPosition = $('.mainTitle').height() + 50;
        if(height > navPosition) {
            $('nav.customers-nav').addClass('nav-fixed');
            $('h1.mainTitle').addClass('customer-spacer');
        } else {
            $('nav.customers-nav').removeClass('nav-fixed');
            $('h1.mainTitle').removeClass('customer-spacer');
        }
    });
});

function dropContent(dropId) {
    var dContent = $('.drop-content#'+dropId);
    var dCard = $('.card-drop#'+dropId);
    var text = $('.drop-content#'+dropId+' > div').height();
    if (dContent.hasClass('opened')) {
        dContent.removeClass('opened');
        dContent.css('height', '0');
        dCard.removeClass('opened');
    } else {
        dContent.addClass('opened');
        dContent.css('height', text);
        dCard.addClass('opened');
    }
}

function readCookieValue(value) {
    if (value[0] === '"') {
        value = value.slice(1, -1)
    }
    return value.replace(/(%[\dA-F]{2})+/gi, decodeURIComponent)
}

function writeCookieValue(value) {
    return encodeURIComponent(value).replace(
        /%(2[346BF]|3[AC-F]|40|5[BDE]|60|7[BCD])/g,
        decodeURIComponent
    )
}

function closeAndAccept() {
    setCookie('cookie-notice-dismissed', 'true', {expires: 365, path: '/'});
    document.getElementById('cookie-notice').style.display = 'none';
}

if (getCookie('cookie-notice-dismissed') !== 'true') {
    document.getElementById('cookie-notice').style.display = 'flex';
}

document.getElementById('cookie-notice-accept').addEventListener("click", closeAndAccept);
document.getElementById('cookie-notice-close').addEventListener("click", closeAndAccept);
